import 'package:realm/realm.dart';

part 'app.realm.dart';

@RealmModel()
class _Car {
  late String make;
  late String model;
  int? kilometers = 500;
}

void main() {
  var config = Configuration.local([Car.schema]);
  var realm = Realm(config);
  var car = Car('Tesla', 'Model Y', kilometers: 5);
  realm.write(() => realm.add(car));
  var cars = realm.all<Car>().query(r'make == $0', ['Tesla']);
  cars.changes.listen((c) => print('Inserted: ${c.inserted}'));
}
